function show(v: any): void {
  try {
    JSON.stringify(v);
  } catch (e) {
    console.log((e as Error).name);
    console.log((e as Error).message);
  }
}
function main(): void {
  const a: Record<string, any> = {};
  a["self"] = a;
  show(a);
  const b: any = { inner: { list: [1, { back: null }] } };
  b.inner.list[1].back = b;
  show(b);
  const c: any[] = [1];
  c.push({ c });
  show(c);
  const d: Record<string, any> = { x: { y: { z: { w: {} } } } };
  d.x.y.z.w.loop = d.x;
  show(d);
  const o: any = {};
  o.self = o;
  show(o);
}
